const norm=s=>String(s||'').toLowerCase().normalize('NFKC').replace(/[^\p{L}\p{N}]+/gu,' ').trim();
const byMember=new Map();
for(const [bans,members] of topics)for(const w of members.split(' '))if(!byMember.has(w))byMember.set(w,bans);
const forms=w=>[w,w.replace(/ies$/,'y'),w.replace(/(?:s|ed|ing|ly|ment|ness|ation|al)$/,''),w.replace(/(?:ing|ed|ion)$/,'e')];
export function forbiddenWords(item){
 const target=norm(item.front);
 const parts=target.split(' '), matched=parts.flatMap(forms).map(w=>byMember.get(w)).find(Boolean);
 const type=item.extra||'';
 const general=/\(v\b/.test(type)?'do action someone something':/\(adj\b/.test(type)?'very kind quality opposite':/\(adv\b/.test(type)?'way how often manner':/\(n\b/.test(type)?'thing name kind example':'word letter means sounds';
 const provided=Array.isArray(item.banned)?item.banned.filter(w=>typeof w==='string'&&w.length<=40):[];
 const related=[...provided,...(Object.hasOwn(specific,target)?specific[target]:matched||'').split(' ')];
 if(!related.some(Boolean)){
  // Include the definition and constituent words before general clue restrictions for new personal vocabulary.
  related.push(...parts.filter(w=>w.length>2&&parts.length>1),...String(item.back||'').split(/[,;/()]/).map(norm).filter(w=>w&&w.length<=40));
 }
 return [...new Set([...related,...general.split(' '),'letter','rhyme','spelling','translation','sound'].map(norm).filter(w=>w&&w!==target))].slice(0,4);
}
export function violation(clue,word,banned){
 const phrase=' '+norm(clue)+' ';
 return [word,...banned].find(w=>phrase.includes(' '+norm(w)+' '))||null;
}
